pub(crate) fn spawn_error_message(
    kind: ExternalAgentProviderKind,
    error: &io::Error,
) -> String {
    match error.kind() {
        io::ErrorKind::NotFound => format!(
            "{} executable was not found. Install or expose it on PATH, then refresh provider status.",
            kind.label()
        ),
        io::ErrorKind::PermissionDenied => {
            format!("{} executable could not be started due to OS permission.", kind.label())
        }
        _ => ProviderFailureHint::execution_failed().message(kind),
    }
}

fn claude_plan(
    endpoint: &str,
    extra: &str,
    purpose: ExternalAgentLaunchPurpose,
) -> Result<ExternalAgentLaunchPlan, String> {
    let config = serde_json::to_string(&json!({
        "mcpServers": {
            "gameengine": {
                "type": "http",
                "url": endpoint,
                "headers": {"Authorization": "Bearer ${GAMEENGINE_MCP_AUTH_TOKEN}"}
            }
        }
    }))
    .map_err(|error| error.to_string())?;
    let permission_mode = match purpose {
        ExternalAgentLaunchPurpose::BuildOrRepair => "acceptEdits",
        ExternalAgentLaunchPurpose::RuntimeEvaluation => "plan",
    };
    let mut args = os_args(&[
        "-p",
        "--output-format", "stream-json",
        "--verbose",
        "--permission-mode", permission_mode,
        "--strict-mcp-config",
        "--mcp-config",
    ]);
    args.push(OsString::from(config));
    args.extend(os_args(&["--allowedTools", "mcp__gameengine"]));
    args.extend(direct_args(extra).into_iter().map(OsString::from));
    args.push(OsString::from(provider_prompt(purpose)));
    Ok(ExternalAgentLaunchPlan {
        program: OsString::from("claude"),
        args,
    })
}

fn codex_plan(
    endpoint: &str,
    extra: &str,
    purpose: ExternalAgentLaunchPurpose,
) -> ExternalAgentLaunchPlan {
    let sandbox = match purpose {
        ExternalAgentLaunchPurpose::BuildOrRepair => "workspace-write",
        ExternalAgentLaunchPurpose::RuntimeEvaluation => "read-only",
    };
    let quoted_endpoint =
        serde_json::to_string(endpoint).unwrap_or_else(|_| "\"http://127.0.0.1/invalid\"".to_owned());
    let mut args = vec![
        OsString::from("-c"),
        OsString::from("approval_policy=\"never\""),
        OsString::from("-c"),
        OsString::from(format!("mcp_servers.gameengine.url={quoted_endpoint}")),
        OsString::from("-c"),
        OsString::from("mcp_servers.gameengine.bearer_token_env_var=\"GAMEENGINE_MCP_AUTH_TOKEN\""),
        OsString::from("-c"),
        OsString::from("mcp_servers.gameengine.default_tools_approval_mode=\"approve\""),
    ];
    args.extend(os_args(&[
        "exec",
        "--json",
        "--ephemeral",
        "--skip-git-repo-check",
        "--sandbox",
        sandbox,
    ]));
    args.extend(direct_args(extra).into_iter().map(OsString::from));
    args.push(OsString::from(provider_prompt(purpose)));
    ExternalAgentLaunchPlan {
        program: OsString::from("codex"),
        args,
    }
}

fn provider_prompt(purpose: ExternalAgentLaunchPurpose) -> &'static str {
    match purpose {
        ExternalAgentLaunchPurpose::BuildOrRepair => {
            "Follow GAMEENGINE_AGENT_PROPOSAL_JSON. Use the injected gameengine MCP server for persisted authoring, and the current managed workspace only for code. Do not commit, push, bypass permissions, or claim host completion."
        }
        ExternalAgentLaunchPurpose::RuntimeEvaluation => {
            "Evaluate only GAMEENGINE_AGENT_RUNTIME_EVALUATION_CONTEXT and its host-captured frame. Do not mutate project/workspace state. Provider success never completes the GameEngine run."
        }
    }
}

